export const BODY: string = "\n<p>صورتك جاهزة، لكن المنصة تريد 300 DPI وملفك يقول 72، أو لا يقول شيئًا. الحل يستغرق أقل من دقيقة بمجرد أن تعرف الخطوات.</p>\n<p>هذا الدليل يأخذك خطوة بخطوة لتغيير DPI صورة في أربع خطوات عملية: رفع واختيار القيمة والتحقق من الشارة والتنزيل. ويغطي أيضًا الدفعات ولقطات الشاشة والمشاكل الشائعة.</p>\n<p>لا برنامج للتثبيت ولا حساب للإنشاء ولا بكسل يُتلف. التغيير تعديل بيانات وصفية، فتبدو صورتك مطابقة تمامًا عندما تنتهي.</p>\n<h2 id=\"what-you-need\">ما تحتاجه قبل أن تبدأ</h2>\n<p>تحتاج ملفات الصور بصيغة JPEG أو PNG. هاتان الصيغتان الوحيدتان اللتان تحفظان وسم DPI بطريقة معيارية، فالأداة تقبل هاتين الصيغتين فقط.</p>\n<p>اعرف قيمة DPI التي تريدها وجهتك: مطابع الكتب والمجلات تطلب غالبًا 300، والطبعات التجريبية تقبل 150، والشاشات تكتفي بـ72 أو 96. وراجع أبعاد البكسلات قبل أن تبدأ: لا يستطيع DPI إنقاذ صورة ببكسلات قليلة جدًا، فتأكد من أن الأبعاد كبيرة بما يكفي لحجم الطباعة.</p>\n<p>المتصفح هو كل البرامج التي تحتاجها: تعمل الأداة في Chrome وSafari وFirefox وEdge، على الحاسوب والهاتف، دون أي إضافة.</p>\n<h2 id=\"step-1-upload\">الخطوة 1: ارفع ملفات JPEG أو PNG</h2>\n<p>افتح <a href=\"/ar/taghyir-dpi-as-sura/\">مغيّر DPI الصورة</a> واسحب ملفاتك إلى منطقة الرفع. يمكنك إسقاط صورة واحدة أو دفعة كاملة دفعة واحدة.</p>\n<p>ويمكنك أيضًا النقر على منطقة الرفع للتصفح، أو لصق لقطة شاشة من الحافظة بـCtrl+V لوسمها فورًا دون حفظها أولًا. ويظهر كل ملف في قائمة بقيمة DPI الحالية بجانبه: كثير من الصور ستقرأ قبل: غير محدد، ما يعني ببساطة أن الملف ليس له وسم DPI بعد.</p>\n<p>إذا رُفض ملف، راجع صيغته: ملفات WebP وHEIC وBMP وGIF وSVG غير مدعومة هنا، وستخبرك الأداة بذلك بدل الفشل بصمت.</p>\n<h2 id=\"step-2-choose-the-value\">الخطوة 2: اختر إعدادًا أو DPI مخصصًا</h2>\n<p>اختر واحدًا من الإعدادات الخمسة: 72 للشاشة و96 لـWindows و150 لطباعة تجريبية و300 لطباعة عالية و600 لعمل أرشيفي. لمعظم أعمال النشر، 300 هو الاختيار الصحيح.</p>\n<p>وإذا طلبت وجهتك رقمًا مختلفًا، اكتبه في حقل DPI المخصص: يُقبل أي عدد صحيح من 1 إلى 2400، فقيم مثل 200 أو 350 تعمل جيدًا. وتُطبق نفس القيمة على كل ملف في الدفعة: إذا احتاجت صور مختلفة قيم DPI مختلفة، عالجها في دفعات منفصلة، قيمة واحدة في كل مرة.</p>\n<p>راجع الرقم قبل المعالجة: خطأ طباعي يحول 300 إلى 3000 سهل الارتكاب وسيُكتب بأمانة، فاقرأ الحقل مرة أخرى.</p>\n<h2 id=\"step-3-process-and-verify\">الخطوة 3: عالج وابحث عن شارة التحقق</h2>\n<p>انقر لمعالجة الملفات: تعيد الأداة كتابة وسم DPI في ترويسة كل ملف ثم تعيد قراءة الملف لتأكيد أن القيمة الجديدة حُفظت بشكل صحيح.</p>\n<p>يُظهر كل ملف ناجح شارة DPI متحقق: تلك الشارة هي تأكيدك أن الملف سيبلغ نفس DPI في أي قارئ متوافق مع المعايير، بما فيه منصتك. وإذا أظهر ملف خطأ، اقرأ الرسالة: JPEG تالف أو صيغة غير مدعومة سيُوسم بوضوح، وبقية الدفعة ستُعالج بشكل طبيعي.</p>\n<p>لا تتخطَّ خطوة التحقق: ملف عولج لكنه لم يُتحقق منه هو تخمين، وإرسال فاشل يكلف وقتًا أطول بكثير من نظرة ثانية إلى الشارة.</p>\n<h2 id=\"step-4-download\">الخطوة 4: نزّل الملفات الموسومة</h2>\n<p>نزّل كل ملف منفصلًا، أو انقر تنزيل ZIP للحصول على الدفعة كلها في ملف واحد: يحتفظ ZIP بأسماء الملفات الأصلية، فتعود الصور مباشرة إلى مستندك أو ملف التصميم.</p>\n<p>أسماء ملفات الإخراج واضحة لتستطيع تمييزها عن الأصول. واحتفظ بالأصول أيضًا، لتكون لديك دائمًا نسخة سليمة تعود إليها. وافتح ملفًا منزّلًا في منصتك أو في عارض صور وتأكد من أن DPI يُقرأ بشكل صحيح: ذلك التحقق الأخير يستغرق ثوانٍ ويكتشف أي سوء فهم قبل الإرسال.</p>\n<p>أرسل الملفات الموسومة إلى منصتك. وإذا اشتكت المنصة مع ذلك، فالمشكلة غالبًا أبعاد البكسلات لا DPI، فراجعها بعدها.</p>\n<h2 id=\"batch-changing-dpi\">كيف تغيّر DPI دفعة كاملة</h2>\n<p>الكتب والكتالوجات ومقالات المجلات تحتاج عشرات الصور بنفس DPI: سير الدفعة يتعامل معها كلها في تمريرة واحدة بضبط واحد.</p>\n<p>أسقط المجلد كله في الأداة واختر القيمة مرة واحدة: كل ملف يُوسم ويُتحقق منه ويُدرج بشارته، فتستطيع رؤية بنظرة إن فشل أي ملف. ونزّل الدفعة كـZIP واحد: يحفظ الأرشيف أسماء الملفات، وهو أمر مهم عندما تُشار إلى الصور بالاسم في مستند أو ملف تصميم.</p>\n<p>وإذا كانت ملفات قليلة في الدفعة WebP أو HEIC، حوّلها أولًا: <a href=\"/ar/tahwil-as-suwar/\">محوّل الصور</a> يحوّلها إلى JPG أو PNG، ثم يمكنها الانضمام إلى الدفعة التالية.</p>\n<h2 id=\"dpi-for-print-publishing\">DPI للنشر المطبوع والمجلات</h2>\n<p>منصات كتب مثل Amazon KDP تراجع DPI كل صورة في المخطوطة: غلاف أو صورة داخلية موسومة دون حدها الأدنى تُرفض، ويتوقف الإرسال كله.</p>\n<p>المجلات الأكاديمية أشد صرامة: كثير منها يتطلب 300 DPI للصور الفوتوغرافية و600 DPI للفن الخطي، وتراجع الوسم قبل مراجعة المحتوى. والسير نفسه في الحالتين: تأكد من أبعاد البكسلات أولًا، وسم DPI ثانيًا، وتحقق من الشارة ثالثًا، وأرسل رابعًا. وتخطي الخطوة الأولى هو أكثر أسباب الفشل شيوعًا.</p>\n<p>وللفن الخطي، استخدم إعداد 600 DPI: الخطوط الرفيعة والنص الصغير يحتاجان الكثافة الإضافية، ورسم خطي بـ300 DPI قد يبدو متعرجًا عند طباعته بالحجم الكامل.</p>\n<h2 id=\"fixing-a-72-dpi-file\">كيف تصلح ملف 72 DPI مرفوضًا</h2>\n<p>رفض 72 DPI هو أكثر مشاكل DPI شيوعًا، وهو أيضًا الأسهل إصلاحًا: البكسلات غالبًا جيدة؛ فقط وسم البيانات الوصفية خطأ.</p>\n<p>ارفع الملف واختر إعداد 300 DPI وعالجه: تعيد الأداة كتابة الوسم وتتحقق منه، والملف المنزّل يجتاز مراجعة المنصة. وقبل إعادة إرساله، تأكد من الأبعاد: ملف 72 DPI صغير البكسلات أيضًا سيفشل مجددًا، هذه المرة بسبب الأبعاد، ولا قيمة DPI تستطيع إصلاح ذلك.</p>\n<p>وإذا كان الملف لقطة شاشة، ينطبق نفس الحل: اللقطات غالبًا تحمل وسم 72 أو 96 DPI، ووسمها إلى 300 DPI يجعلها مقبولة لسير الطباعة.</p>\n<h2 id=\"dpi-for-screenshots\">DPI للقطات الشاشة</h2>\n<p>لقطات الشاشة هي أسرع حل DPI من كل شيء، لأنك تستطيع لصقها مباشرة من الحافظة: انسخ الشاشة واضغط Ctrl+V في الأداة فتظهر اللقطة جاهزة للوسم.</p>\n<p>اختر 300 DPI للقطة ستظهر في دليل مطبوع أو كتاب: البكسلات هي ما التقطته الشاشة، لكن الوسم سيرضي سير الطباعة. وكن صادقًا بشأن الحدود: لقطة مربع حوار صغير لها بكسلات قليلة، ووسمها إلى 300 DPI يجعلها طباعة صغيرة جدًا، لا كبيرة وحادة.</p>\n<p>وللقطات يجب طباعتها كبيرة، التقطها أولًا بمقياس شاشة أعلى: لقطة مأخوذة على شاشة ريتينا تحمل ضعف البكسلات وتُطبع بضعف الحجم.</p>\n<h2 id=\"removing-dpi-tags\">كيف تزيل وسم DPI</h2>\n<p>أحيانًا لا تريد أي وسم DPI، بدل وسم مختلف: تستطيع الأداة إزالة بيانات DPI الوصفية من ملف وترك البكسلات سليمة.</p>\n<p>الإزالة مفيدة عندما يحمل ملف وسمًا غير صحيح يربك برنامجك: صورة موسومة بقيمة غريبة قد تجعل برنامج تصميم يقيّمها بشكل غير متوقع. ولإزالة الوسم، استخدم خيار الإزالة في الأداة وعالج الملف: الملف المنزّل ليس له بيانات DPI وصفية، والبرنامج الذي يفتحه سيعود إلى قيمته الافتراضية.</p>\n<p>أزل وسمًا فقط عندما يكون لديك سبب: معظم سير النشر تريد الوسم موجودًا، وملف دون وسم قد يُرفض بسهولة مثل ملف موسوم خطأ.</p>\n<h2 id=\"troubleshooting-formats\">حل المشاكل: صيغ غير مدعومة</h2>\n<p>إذا رفضت الأداة ملفك، أول ما تراجعه هو الصيغة: ملفات WebP وHEIC وBMP وGIF وSVG غير مدعومة، وستخبرك الأداة بذلك بوضوح.</p>\n<p>حوّل الملف إلى JPG أو PNG وحاول مجددًا: <a href=\"/ar/tahwil-as-suwar/\">محوّل الصور</a> يتعامل مع WebP وHEIC، والتحويل يحافظ على البكسلات بينما يمنح الملف صيغة تستطيع حمل وسم DPI. وانتبه للملفات المسماة خطأ: ملف WebP محفوظ بامتداد .jpg سيُرفض حتى لو بدا اسمه جيدًا، لأن الأداة تقرأ محتوى الملف الحقيقي.</p>\n<p>وعند الشك، افتح الملف في عارض صور واحفظه مجددًا كـJPG أو PNG: حفظ نظيف يضمن أن الصيغة تطابق الامتداد.</p>\n<h2 id=\"troubleshooting-corrupt-files\">حل المشاكل: ملفات تالفة</h2>\n<p>JPEG تالف سيفشل مع رسالة خطأ، وبقية الدفعة ستستمر في المعالجة: الخطأ خاص بذلك الملف، لا بالأداة.</p>\n<p>جرّب فتح الملف في عارض صور: إذا فشل العارض أيضًا، فالملف تالف ويحتاج تنزيلًا مجددًا أو تصديرًا مجددًا من مصدره. وملف يفتح في العارض لكنه يفشل في الأداة قد يكون له ترويسة تالفة: إعادة حفظه من العارض تكتب ترويسة جديدة، والملف الجديد غالبًا يُعالج.</p>\n<p>لا ترسل أبدًا ملفًا لم يُعالج: ملف تالف يتسلل إلى عمل طباعة قد يوقف الإرسال كله، فأصلحه أو استبدله قبل المتابعة.</p>\n<h2 id=\"checking-the-result\">كيف تتحقق من النتيجة بعد التنزيل</h2>\n<p>بعد التنزيل، افتح ملفًا وتأكد من DPI: في Windows، انقر بزر اليمين على الملف واختر خصائص وانظر إلى تبويب التفاصيل. وفي Mac، افتحه في Preview وراجع الفاحص.</p>\n<p>يجب أن يطابق الرقم ما اخترته: JPEG موسوم بـ300 DPI يُقرأ 300، بينما PNG قد يُقرأ 299 بسبب طريقة حفظ PNG للدقة بالبكسلات لكل متر. وإذا كان الرقم خطأ، أعد معالجة الأصل بدل الملف المنزّل: إعادة وسم ملف موسوم تعمل، لكن البدء من الأصل يبقي سلسلة التغييرات نظيفة.</p>\n<p>دوّن القيمة التي استخدمتها لكل مشروع: عندما تذهب نفس الصور إلى منصة ثانية بقواعد مختلفة، تخبرك الملاحظة ما تغيّره دون إعادة مراجعة كل صورة.</p>\n<h2 id=\"dpi-for-ecommerce\">DPI لصور التجارة الإلكترونية والأسواق</h2>\n<p>صور السوق تعيش على شاشات، فيبدو DPI غير ذي صلة بها، لكن البائعين ما زالوا يتعثرون به. الالتباس غالبًا يبدأ عندما تذكر صفحة مساعدة DPI دون شرح ما يهم.</p>\n<p>لإعلانات المنتج، أبعاد البكسلات هي القاعدة المهمة: سوق يريد 1000 بكسل في أطول جانب يراجع عدد البكسلات، لا وسم DPI، وملف بـ300 DPI لكنه صغير البكسلات سيفشل مع ذلك. ومع ذلك، وسم صور السوق إلى 300 DPI لا يضر وأحيانًا يساعد: بعض أدوات البائعين وخدمات الطباعة عند الطلب تقرأ الوسم، وقيمة صحيحة تمنع المفاجآت.</p>\n<p>النهج العملي هو إصلاح البكسلات أولًا وDPI ثانيًا: تأكد من الأبعاد بفاحص الأبعاد، وغيّر الحجم إن لزم، ثم وسم 300 DPI كخطوة أخيرة قبل الرفع. ولمنتجات الطباعة عند الطلب مثل الأكواب والقمصان والملصقات، يهم DPI كثيرًا: المنتج يُطبع، فينطبق نفس معيار 300 DPI، وعدد البكسلات يقرر حجم الطباعة.</p>\n<p>راجع متطلبات الطباعة عند الطلب لكل منتج قبل الرفع: تصميم يعمل على كوب قد يكون صغيرًا جدًا لملصق، ووسم DPI وحده لن يغطي الفرق.</p>\n<h2 id=\"re-applying-different-dpi\">كيف تطبق قيمة DPI مختلفة</h2>\n<p>المشاريع تتغير، وملف موسوم بـ300 DPI قد يحتاج لاحقًا 600 DPI لملف أرشيف أو طباعة فنية: تتيح الأداة تطبيق قيمة جديدة على نفس الملفات.</p>\n<p>ارفع الملفات مجددًا واختر الإعداد الجديد أو القيمة المخصصة وعالجها: كل تمريرة لا تفقد جودة، فالبكسلات لا تتدهور أبدًا بسبب الوسم المتكرر. ويمكنك أيضًا الذهاب بالعكس، من 600 إلى 300، بنفس الأمان: تُعاد كتابة الترويسة في كل مرة ولا تُمس بيانات البكسلات أبدًا.</p>\n<p>للسياق الكامل حول ما يعنيه DPI، اقرأ <a href=\"/ar/blog/dalil-mughayyir-dpi-as-suwar/\">دليل مغيّر DPI الصور الكامل</a>، وللمقارنة مع PPI الشاشة راجع <a href=\"/ar/blog/dpi-vs-ppi-al-tibaa-wa-al-web/\">DPI مقابل PPI: ما يهم للطباعة والويب</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كم يستغرق تغيير DPI صورة؟","answer":"ثوانٍ: تعيد الأداة كتابة بضع بايتات في ترويسة الملف ولا تعيد ترميز أي بكسل، فحتى دفعة كبيرة تنتهي بسرعة. والوقت الذي تقضيه يكون أساسًا في الرفع والتنزيل."},{"question":"هل يمكنني تغيير DPI صور كثيرة دفعة واحدة؟","answer":"نعم، أسقط الدفعة كلها في الأداة واختر قيمة DPI وكل JPEG وPNG في الدفعة يُوسم في تمريرة واحدة. ونزّل النتائج كملف ZIP واحد مع أسماء الملفات الأصلية محفوظة."},{"question":"ماذا يحدث إذا كتبت DPI مخصصًا خطأ؟","answer":"تكتب الأداة أي رقم تضعه، من 1 إلى 2400، وتتحقق منه بالشارة. وإذا لاحظت الخطأ، أعد معالجة الملفات الأصلية بالقيمة الصحيحة فقط. وكل تمريرة لا تفقد جودة، فالبكسلات تبقى سليمة."},{"question":"هل تغيير DPI يؤثر في جودة الصورة أو ألوانها؟","answer":"لا، تتغير فقط بيانات الدقة الوصفية في الترويسة. وتبقى البكسلات والضغط وبيانات EXIF وملف ICC اللوني كما كانت بالضبط. وتبدو الصورة مطابقة على الشاشة قبل وبعد."},{"question":"هل يمكنني لصق لقطة شاشة وتغيير DPI فورًا؟","answer":"نعم، انسخ اللقطة واضغط Ctrl+V في الأداة فتظهر جاهزة للوسم. واختر 300 DPI للاستخدام المطبوع وعالجها ونزّل النتيجة. وهذه أسرع طريق من لقطة الشاشة إلى الملف الموسوم."},{"question":"لماذا رُفض ملفي من مغيّر DPI؟","answer":"الأسباب الشائعة صيغة غير مدعومة مثل WebP أو HEIC، أو ملف يتجاوز حد الحجم، أو JPEG تالف. وحوّل الصيغ غير المدعومة أولًا إلى JPG أو PNG، وأعد تصدير أي ملف تالف من مصدره."}];
